CREATE TABLE IF NOT EXISTS employees (id TEXT PRIMARY KEY, name TEXT NOT NULL, position TEXT, base_salary REAL DEFAULT 0, is_active BOOLEAN DEFAULT 1, joined_at DATE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payroll_runs (id TEXT PRIMARY KEY, period_month INTEGER NOT NULL, period_year INTEGER NOT NULL, pos_id_source TEXT, total_amount REAL DEFAULT 0, status TEXT DEFAULT 'draft', processed_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(period_month, period_year));
CREATE TABLE IF NOT EXISTS payroll_items (id TEXT PRIMARY KEY, payroll_run_id TEXT NOT NULL, employee_id TEXT NOT NULL, base_salary REAL DEFAULT 0, allowances REAL DEFAULT 0, deductions REAL DEFAULT 0, net_salary REAL DEFAULT 0, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (payroll_run_id) REFERENCES payroll_runs(id) ON DELETE CASCADE, FOREIGN KEY (employee_id) REFERENCES employees(id));
CREATE TABLE IF NOT EXISTS system_config (key TEXT PRIMARY KEY, value TEXT);
